  ('VN-1', 'vn-hai-phong-railway-station', 'it', 'Stazione ferroviaria di Haiphong', 'Stazione ferroviaria nella zona di viaggio Hanoi e delta del Fiume Rosso. Servizi attivi, terminal, accessi, orari e coincidenze da verificare con il gestore; nessuna tratta o tariffa implicita.', 'Accesso, trasferimenti e accessibilità da verificare sulla fonte del luogo.', 'Aperture, condizioni e necessità di prenotazione da verificare per le date del viaggio.', null, null, null, null, null),
  ('VN-1', 'vn-port-of-saigon', 'it', 'porto di Saigon', 'Area portuale nella zona di viaggio Ho Chi Minh City e Vietnam sud-orientale. Servizi attivi, terminal, accessi, orari e coincidenze da verificare con il gestore; nessuna tratta o tariffa implicita.', 'Accesso, trasferimenti e accessibilità da verificare sulla fonte del luogo.', 'Aperture, condizioni e necessità di prenotazione da verificare per le date del viaggio.', null, null, null, null, null);
